mapper.select:
SELECT trades.symbol, trades.symbol_name, COALESCE(types.instrumenttype, 'Other') AS instrument_type, COUNT(*) AS total_trades, COALESCE(SUM(NULLIF(trades.total_value::text, '')::numeric), 0) AS trade_volume FROM sleapy_analytics.expensive_trades trades LEFT JOIN public.instruments instruments ON instruments.symbol = trades.symbol LEFT JOIN public.instrument_type types ON types.instrumenttype_id = instruments.instrumenttype_id
trades.client_id = #{clientId}
GROUP BY trades.symbol, trades.symbol_name, types.instrumenttype ORDER BY total_trades DESC, trade_volume DESC
